CREATE FUNCTION _heroku.validate_extension() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$

DECLARE

  schemaname TEXT;
  r RECORD;

BEGIN

  IF tg_tag = 'CREATE EXTENSION' and current_user != 'rds_superuser' THEN
    FOR r IN SELECT * FROM pg_event_trigger_ddl_commands()
    LOOP
      CONTINUE WHEN r.command_tag != 'CREATE EXTENSION' OR r.object_type != 'extension';

      schemaname = (
        SELECT n.nspname
        FROM pg_catalog.pg_extension AS e
        INNER JOIN pg_catalog.pg_namespace AS n
        ON e.extnamespace = n.oid
        WHERE e.oid = r.objid
      );

      IF schemaname = '_heroku' THEN
        RAISE EXCEPTION 'Creating extensions in the _heroku schema is not allowed';
      END IF;
    END LOOP;
  END IF;
END;
$$;


--
-- Name: create_shipment_for_order(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_shipment_for_order(p_order_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_shipper TEXT;
  v_shipment_id BIGINT;
BEGIN
 
  IF EXISTS (SELECT 1 FROM shipments WHERE order_id = p_order_id) THEN
    RETURN;
  END IF;
SELECT u.username
    INTO v_shipper
  FROM users u
  WHERE u.role = 'shipper'::user_role
  ORDER BY random()
  LIMIT 1;
IF v_shipper IS NULL THEN
    v_shipper := 'shipper01';
  END IF;
  VALUES (p_order_id, v_shipper, 'ASSIGNED', NOW(), NOW())
  RETURNING id INTO v_shipment_id;
  VALUES (v_shipment_id, 'ASSIGNED', 'Shipment automatically assigned', v_shipper, NOW());
END;
$$;


--
-- Name: get_commission_policy(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_commission_policy(total numeric) RETURNS TABLE(id integer, name character varying, rate numeric)
    LANGUAGE plpgsql
    AS $$

BEGIN

  RETURN QUERY

  SELECT id, name, rate

  FROM commissions

  WHERE type = 'doanh sß╗æ'

    AND (total >= COALESCE(min_revenue, 0))

    AND (total <= COALESCE(max_revenue, total))

  ORDER BY rate DESC

  LIMIT 1;

END;

$$;


