BEGIN

  NEW.updated_at = NOW();

  RETURN NEW;

END;

$$;


--
-- Name: sync_promotion_to_coupon(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_promotion_to_coupon() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

BEGIN

    IF NEW.code IS NOT NULL AND TRIM(NEW.code) <> '' THEN


        VALUES (

            NEW.code,

            NEW.description,

            CASE WHEN NEW.discount_type = 'percent' THEN 'percentage' ELSE NEW.discount_type END,

            NEW.discount_value,

            NEW.max_discount_value,

            NEW.min_order_value,

            NEW.start_date,

            NEW.end_date,

            CASE WHEN NEW.status THEN 'active' ELSE 'inactive' END

        )

        ON CONFLICT (code) DO NOTHING;

    END IF;

    RETURN NEW;

END;

$$;


--
-- Name: trg_update_shop_rate_and_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_update_shop_rate_and_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE

  matched_rate NUMERIC(5,2);

  matched_commission_id INT;

BEGIN

  -- X├íc ─æß╗ïnh ch├¡nh s├ích ph├╣ hß╗úp theo doanh thu

  SELECT id, rate INTO matched_commission_id, matched_rate

  FROM commissions

  WHERE type = 'doanh sß╗æ'

    AND (NEW.total_revenue >= COALESCE(min_revenue, 0))

    AND (NEW.total_revenue <= COALESCE(max_revenue, NEW.total_revenue))

  ORDER BY rate DESC

  LIMIT 1;



  -- Cß║¡p nhß║¡t commission_rate trong shops

  UPDATE shops

  SET commission_rate = matched_rate

  WHERE id = NEW.shop_id;



  -- L╞░u lß╗ïch sß╗¡ v├áo shop_commission_history


    shop_id, commission_id, month, year, total_revenue, applied_rate, commission_amount

  )

  VALUES (

    NEW.shop_id,

    matched_commission_id,

    NEW.month,

    NEW.year,

    NEW.total_revenue,

    matched_rate,

    ROUND(NEW.total_revenue * matched_rate / 100, 2)

  )

  ON CONFLICT (shop_id, month, year) DO UPDATE

  SET

    commission_id = EXCLUDED.commission_id,

    total_revenue = EXCLUDED.total_revenue,

    applied_rate = EXCLUDED.applied_rate,

    commission_amount = EXCLUDED.commission_amount,

    created_at = CURRENT_TIMESTAMP;



  RETURN NEW;

END;

$$;


--
-- Name: update_books_based_on_seller_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_books_based_on_seller_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

BEGIN

    -- Nß║┐u seller bß╗ï kh├│a hoß║╖c inactive

    IF NEW.status IN ('inactive', 'banned') THEN

        UPDATE books

        SET status = 'inactive'

        WHERE shop_id IN (

            SELECT id FROM shops WHERE owner_id = NEW.id

        );



    -- Nß║┐u seller ─æ╞░ß╗úc mß╗ƒ lß║íi (active)

    ELSIF NEW.status = 'active' THEN

        UPDATE books

        SET status = 'active'

        WHERE shop_id IN (

            SELECT id FROM shops WHERE owner_id = NEW.id

        );

    END IF;



    RETURN NEW;

END;

$$;


--
-- Name: update_order_status_from_shipment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_order_status_from_shipment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE

    new_order_status TEXT;

    current_order_status TEXT;

BEGIN

    -- Nß║┐u kh├┤ng thay ─æß╗òi g├¼ th├¼ th├┤i

    IF (OLD.status = NEW.status) THEN

        RETURN NEW;

    END IF;



    CASE NEW.status

        WHEN 'ASSIGNED' THEN new_order_status := 'confirmed';

        WHEN 'PICKED_UP' THEN new_order_status := 'shipping';

        WHEN 'OUT_FOR_DELIVERY' THEN new_order_status := 'shipping';

        WHEN 'DELIVERED' THEN new_order_status := 'delivered';

        WHEN 'FAILED_DELIVERY' THEN new_order_status := 'shipping';

        WHEN 'RETURNING' THEN new_order_status := 'shipping';

        WHEN 'RETURNED' THEN new_order_status := 'returned';

        WHEN 'CANCELLED' THEN new_order_status := 'cancelled';

        ELSE new_order_status := NULL;

    END CASE;



    -- Lß║Ñy trß║íng th├íi hiß╗çn tß║íi cß╗ºa order

    SELECT status INTO current_order_status FROM orders WHERE id = NEW.order_id;



    -- Chß╗ë update nß║┐u kh├íc ─æß╗â tr├ính loop

    IF new_order_status IS NOT NULL AND current_order_status IS DISTINCT FROM new_order_status THEN

        UPDATE orders

        SET status = new_order_status,

            updated_at = NOW()

        WHERE id = NEW.order_id;

    END IF;



    RETURN NEW;

END;

$$;


--
-- Name: update_shipment_status_from_order(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_shipment_status_from_order() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE

    new_shipment_status TEXT;

    current_shipment_status TEXT;

BEGIN

    -- Nß║┐u kh├┤ng thay ─æß╗òi g├¼ th├¼ th├┤i

    IF (OLD.status = NEW.status) THEN

        RETURN NEW;

    END IF;



    -- Mapping tß╗½ order.status ΓåÆ shipment.status

    CASE NEW.status

        WHEN 'cancelled' THEN new_shipment_status := 'CANCELLED';

        WHEN 'returned' THEN new_shipment_status := 'RETURNED';

        WHEN 'delivered' THEN new_shipment_status := 'DELIVERED';

        ELSE new_shipment_status := NULL;

    END CASE;



    -- Lß║Ñy trß║íng th├íi hiß╗çn tß║íi cß╗ºa shipment t╞░╞íng ß╗⌐ng

    SELECT status INTO current_shipment_status FROM shipments WHERE order_id = NEW.id;



    -- Chß╗ë cß║¡p nhß║¡t nß║┐u c├│ kh├íc biß╗çt

    IF new_shipment_status IS NOT NULL AND current_shipment_status IS DISTINCT FROM new_shipment_status THEN

        UPDATE shipments

        SET status = new_shipment_status,

            updated_at = NOW()

        WHERE order_id = NEW.id;

    END IF;



    RETURN NEW;

END;

$$;


